class Cache
  def initialize(packer: nil)
    @packer = packer
    @storage = {}
  end

  # Stores payload under key. 
  # If a packer is provided, the entry is dumped before storage.
  def write(key, payload, stale: false)
    # We store a hash containing the payload and the stale flag.
    # This entire metadata wrapper is what gets packed/unpacked.
    data = { payload: payload, stale: stale }

    value = @packer ? @packer.dump(data) : data
    @storage[key] = value
  end

  # Returns the payload most recently written under key, or nil.
  def read(key)
    return nil unless @storage.key?(key)

    entry = @storage[key]
    data = @packer ? @packer.load(entry) : entry
    data[:payload]
  end

  # Removes every entry whose #write call passed stale: true.
  def sweep
    @storage.delete_if do |key, value|
      data = @packer ? @packer.load(value) : value
      data[:stale] == true
    end
  end
end
