class Cache
  def initialize(packer: nil)
    @packer = packer
    @storage = {}
  end

  def write(key, payload, stale: false)
    # The entry needs to store both the payload and its stale status
    entry = { payload: payload, stale: stale }

    if @packer
      # Pack the entire entry object so that status is preserved and serialized
      @storage[key] = @packer.dump(entry)
    else
      @storage[key] = entry
    end
  end

  def read(key)
    entry = get_entry(key)
    return nil unless entry

    entry[:payload]
  end

  def sweep
    @storage.delete_if do |key, _|
      entry = get_entry(key)
      # Remove if the entry exists and was marked as stale
      entry && entry[:stale]
    end
  end

  private

  def get_entry(key)
    data = @storage[key]
    return nil if data.nil?

    if @packer
      @packer.load(data)
    else
      data
    end
  end
end
