class Money
  include Comparable

  attr_reader :cents

  def initialize(cents)
    @cents = cents
  end

  # The Comparable module requires the implementation of <=>
  # This enables <, >, <=, >=, between, and sorting.
  def <=>(other)
    return nil unless other.is_a?(Money)
    @cents <=> other.cents
  end

  # While Comparable provides == via <=> in some versions/contexts,
  # it is standard practice to define == explicitly for value objects.
  def ==(other)
    return false unless other.is_a?(Money)
    @cents == other.cents
  end
end
