class Reading
  attr_reader :whole, :fraction

  def initialize(whole, fraction)
    @whole = whole
    @fraction = fraction
  end

  # Returns the total value as a Rational to ensure precision.
  # Adding an Integer and a Rational in Ruby results in a Rational.
  def exact
    @whole + @fraction
  end

