class Registry
  def initialize
    # We use a Set to keep track of object identity for O(1) lookup,
    # but since we need to maintain insertion order for #to_a, 
    # we use an Array to store the sequence.
    @objects = []
    @seen = {}
  end

  def register(obj)
    # Use object_id to ensure we are tracking the identical object,
    # not just objects that are equal (==).
    unless @seen.key?(obj.object_id)
      @seen[obj.object_id] = true
      @objects << obj
    end
    self
  end

  def registered?(obj)
    # Check if the specific object's identity exists in our registry.
    @seen.key?(obj.object_id)
  end

  def size
    @objects.size
  end

  def to_a
    # Return a copy of the array to prevent external modification of the internal state.
    @objects.dup
  end
end
