class Registry
  def initialize
    # We use an array to maintain insertion order for #to_a.
    # We use a Set or a Hash (with keys) to ensure object-identity uniqueness.
    # Since we need identity check (not equality check), we can't use a standard
    # Set/Hash directly because they rely on #hash and #eql?.
    # However, in Ruby, we can use a Hash with an identity-based approach or 
    # simply iterate through the array using `equal?`.
    @objects = []
  end

  def register(obj)
    # check if the exact same object identity is already present
    unless @objects.any? { |item| item.equal?(obj) }
      @objects << obj
    end
    self
  end

  def registered?(obj)
    @objects.any? { |item| item.equal?(obj) }
  end

  def size
    @objects.size
  end

  def to_a
    @objects.dup
  end
end
