class OpenRecord
  def initialize(**attrs)
    @data = attrs
  end

  def method_missing(method_name, *args, &block)
    # Handle setter methods (e.g., name=)
    if method_name.to_s.end_with?('=')
      attr_name = method_name.to_s.chop.to_sym
      @data[attr_name] = args[0]
      return @data[attr_name]
    end

    # Handle getter methods
    if @data.key?(method_name)
      return @data[method_name]
    end

    super
  end

  def respond_to_missing?(method_name, include_private = false)
    # Every OpenRecord can respond to any setter (dynamic attribute store)
    return true if method_name.to_s.end_with?('=')

    # Responds to getter if the key exists in the internal store
    return true if @data.key?(method_name)

    super
  end
end
