class OpenRecord
  def initialize(**attrs)
    @data = attrs
  end

  # Handle getter methods and respond_to?
  def method_missing(method_name, *args, &block)
    name = method_name.to_s

    if name.end_with?('=')
      # Handle setter methods (e.g., record.age = 37)
      attr_name = name.chop.to_sym
      @data[attr_name] = args.first
    else
      # Handle getter methods
      if @data.key?(method_name)
        @data[method_name]
      else
        super
      end
    end
  end

  # Ensure respond_to? returns true for defined getters and all potential setters
  def respond_to?(method_name, include_private = false)
    name = method_name.to_s

    # Always respond to any setter (e.g., name=)
    return true if name.end_with?('=')

    # Respond to getters only if the key exists in the data store
    @data.key?(method_name) || super
  end

  # This is important for Ruby's internal consistency when respond_to? is overridden
  def respond_to_missing?(method_name, include_private = false)
    name = method_name.to_s
    name.end_with?('=') || @data.key?(method_name)
  end
end
