class StockCount
  attr_reader :count

  def initialize(count)
    @count = count
  end

  def -(other)
    # Determine the value to subtract
    # If 'other' is a StockCount, use its #count; otherwise, use the value itself
    value_to_subtract = other.is_a?(StockCount) ? other.count : other

    # Calculate difference and ensure the result is returned as a Float
    (@count - value_to_subtract).to_f
  end

  def ==(other)
    # Two StockCounts are equal if their counts are equal
    return false unless other.is_a?(StockCount)
    @count == other.count
  end
end
